:host {
  display: inline-flex;
  min-inline-size: 0;
  max-inline-size: var(--dimension-menu-width-xs);
}

:host([hidden]) {
  display: none;
}

import {
  Component,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Method,
  Prop,
  State,
} from '@stencil/core';
import type { MenuItemData } from '../Menu/menu-types';
import type { TableColumn, TableSortChangeDetail, TableSortState } from '../Table/table-types';
import {
  nextTableSortStateFromMenuItem,
  tableSortFields,
  tableSortMenuSections,
  tableSortStatesEqual,
} from './table-sort-menu';

let tableSortSeq = 0;

@Component({
  tag: 'ds-table-sort',
  styleUrl: 'TableSort.css',
  scoped: true,
})
export class TableSort {
  @Element() private el!: HTMLElement;

  /** Catalog used to derive sortable fields, including compound header segments. */
  @Prop() columns: TableColumn[] = [];
  /** Controlled table sort. Header sorting and this menu share the same value. */
  @Prop() sort: TableSortState | null = null;
  /** Accessible name for the trigger and menu. */
  @Prop({ attribute: 'aria-label' }) ariaLabel: string | null = null;

  @Event({ bubbles: false }) dsSortChange!: EventEmitter<TableSortChangeDetail>;

  @State() private menuOpen = false;
  @State() private initialFocusVisible = false;

  private readonly componentId = `ds-table-sort-${++tableSortSeq}`;
  private readonly triggerId = `${this.componentId}-trigger`;
  private readonly menuId = `${this.componentId}-menu`;

  @Method()
  async setFocus() {
    const trigger = this.el.querySelector<HTMLElement & { setFocus?: () => Promise<void> }>(
      `#${CSS.escape(this.triggerId)}`
    );
    await trigger?.setFocus?.();
  }

  render() {
    const fields = tableSortFields(this.columns);
    const name = this.ariaLabel?.trim() || 'Sort table';

    return (
      <Host hidden={fields.length === 0 ? true : undefined}>
        {fields.length === 0 ? null : (
          <ds-button-unfilled
            id={this.triggerId}
            variant="icon-label"
            size="md"
            icon="ArrowsVertical"
            label="Sort"
            labelEmphasis={false}
            pressScale={false}
            aria-label={name}
            hasMenu={true}
            collapseLabel={true}
            expanded={this.menuOpen}
            controls={this.menuId}
            onDsClick={(event: CustomEvent<MouseEvent>) => {
              this.toggle(event.detail.detail === 0);
            }}
          />
        )}
        {fields.length === 0 ? null : (
          <ds-menu
            id={this.menuId}
            open={this.menuOpen}
            anchorId={this.triggerId}
            align="start"
            side="bottom"
            menuLabel={name}
            selectionMode="none"
            initialFocusVisible={this.initialFocusVisible}
            sections={tableSortMenuSections(this.columns, this.sort)}
            onDsClose={() => this.close()}
            onDsSelect={event => this.handleSelect(event.detail)}
          />
        )}
      </Host>
    );
  }

  private toggle(fromKeyboard = false): void {
    if (this.menuOpen) this.close();
    else this.open(fromKeyboard);
  }

  private open(fromKeyboard = false): void {
    if (this.menuOpen) return;
    this.initialFocusVisible = fromKeyboard;
    this.menuOpen = true;
  }

  private close(): void {
    this.menuOpen = false;
  }

  private handleSelect(item: MenuItemData): void {
    const next = nextTableSortStateFromMenuItem(this.columns, this.sort, item);
    if (tableSortStatesEqual(this.sort, next)) return;
    this.dsSortChange.emit({ sort: next });
  }
}

import type { MenuItemData, MenuSection } from '../Menu/menu-types';
import { isTableActionColumn } from '../Table/table-column-customizer';
import type { TableColumn, TableSortState } from '../Table/table-types';

export const TABLE_SORT_DIRECTION_ASC = 'direction:asc';
export const TABLE_SORT_DIRECTION_DESC = 'direction:desc';
const TABLE_SORT_FIELD_PREFIX = 'field:';

export interface TableSortField {
  id: string;
  label: string;
}

/** Sortable data fields from the catalog, including compound header segments. */
export function tableSortFields(columns: readonly TableColumn[]): TableSortField[] {
  const fields: TableSortField[] = [];
  const seen = new Set<string>();

  for (const column of columns) {
    if (isTableActionColumn(column) || !column.sortable) continue;
    const segments = column.headerSegments?.filter(segment => segment.sortKey.trim()) ?? [];
    if (segments.length > 0) {
      for (const segment of segments) {
        if (seen.has(segment.sortKey)) continue;
        seen.add(segment.sortKey);
        fields.push({
          id: segment.sortKey,
          label: segment.dataLabel?.trim() || segment.label.trim() || segment.sortKey,
        });
      }
      continue;
    }
    if (seen.has(column.id)) continue;
    seen.add(column.id);
    fields.push({
      id: column.id,
      label:
        column.dataLabel?.trim() || column.header.trim() || column.headerLabel?.trim() || column.id,
    });
  }

  return fields;
}

export function tableSortMenuSections(
  columns: readonly TableColumn[],
  sort: TableSortState | null | undefined
): MenuSection[] {
  const fields = tableSortFields(columns);
  return [
    {
      header: 'Data',
      items: fields.map(field => ({
        label: field.label,
        value: `${TABLE_SORT_FIELD_PREFIX}${encodeURIComponent(field.id)}`,
        isSelected: sort?.columnId === field.id,
      })),
    },
    {
      header: 'Direction',
      items: [
        {
          label: 'Ascending',
          value: TABLE_SORT_DIRECTION_ASC,
          icon: 'ArrowUp',
          isSelected: sort?.direction === 'asc',
        },
        {
          label: 'Descending',
          value: TABLE_SORT_DIRECTION_DESC,
          icon: 'ArrowDown',
          isSelected: sort?.direction === 'desc',
        },
      ],
    },
  ];
}

export function tableSortStatesEqual(
  left: TableSortState | null | undefined,
  right: TableSortState | null | undefined
): boolean {
  if (left === right) return true;
  if (!left || !right) return false;
  return left.columnId === right.columnId && left.direction === right.direction;
}

/** Next controlled sort from a Sort menu selection. Does not toggle like a header click. */
export function nextTableSortStateFromMenuItem(
  columns: readonly TableColumn[],
  current: TableSortState | null | undefined,
  item: MenuItemData
): TableSortState | null {
  const fields = tableSortFields(columns);
  if (fields.length === 0) return current ?? null;

  if (item.value === TABLE_SORT_DIRECTION_ASC || item.value === TABLE_SORT_DIRECTION_DESC) {
    const direction = item.value === TABLE_SORT_DIRECTION_ASC ? 'asc' : 'desc';
    const columnId = fields.some(field => field.id === current?.columnId)
      ? current!.columnId
      : fields[0]!.id;
    return { columnId, direction };
  }

  if (!item.value?.startsWith(TABLE_SORT_FIELD_PREFIX)) return current ?? null;
  let columnId: string;
  try {
    columnId = decodeURIComponent(item.value.slice(TABLE_SORT_FIELD_PREFIX.length));
  } catch {
    return current ?? null;
  }
  if (!fields.some(field => field.id === columnId)) return current ?? null;
  if (current?.columnId === columnId) return current ?? null;
  return { columnId, direction: current?.direction ?? 'asc' };
}
